"""
Healthcare module for managing patient prescription and diagnosis data.

Note: This module uses primitive types (strings, lists) instead of
domain models for simplicity, as requested.
"""

import re
from typing import List, Optional, Dict, Tuple


# ---------------------------------------------------------------------------
# Validation helpers
# ---------------------------------------------------------------------------

MRN_PATTERN = re.compile(r'^[A-Za-z0-9\-]{4,20}$')
ICD10_PATTERN = re.compile(r'^[A-TV-Z][0-9][0-9AB](\.[0-9A-Z]{1,4})?$')
NDC_PATTERN = re.compile(r'^\d{4,5}-\d{3,4}-\d{1,2}$')

VALID_UNITS = {
    "mg", "g", "mcg", "ml", "l", "units", "iu", "mEq", "tablet", "capsule",
    "patch", "drop", "puff", "spray"
}


def validate_mrn(patient_mrn: str) -> bool:
    """Validate a patient MRN (Medical Record Number) string."""
    if not isinstance(patient_mrn, str):
        return False
    return bool(MRN_PATTERN.match(patient_mrn.strip()))


def validate_diagnosis_code(code: str) -> bool:
    """Validate an ICD-10-like diagnosis code."""
    if not isinstance(code, str):
        return False
    return bool(ICD10_PATTERN.match(code.strip().upper()))


def validate_medication_code(code: str) -> bool:
    """Validate an NDC-like medication code."""
    if not isinstance(code, str):
        return False
    return bool(NDC_PATTERN.match(code.strip()))


def validate_dosage(dosage: float) -> bool:
    """Validate that dosage is a positive, finite number."""
    try:
        value = float(dosage)
    except (TypeError, ValueError):
        return False
    if value != value or value in (float("inf"), float("-inf")):
        return False
    return value > 0


def validate_unit(unit: str) -> bool:
    """Validate that unit is a recognized dosage unit."""
    if not isinstance(unit, str):
        return False
    return unit.strip().lower() in VALID_UNITS


